mapper.sql:
where 1=1

		and cerl_llave = #{llaveTabla}


		and cerl_estado = #{estado}


		and cerl_usuario = #{usuario}


		and cerl_rolacceso = #{rolAcceso}


		and cerl_documento = #{documento}


		and derl_fechainicial >= #{fechaInicialMin}


		and derl_fechainicial  <   #{fechaInicialMax}


		and derl_fechafinal >= #{fechaFinalMin}


		and derl_fechafinal  <   #{fechaFinalMax}


		and ((select upper(cusr_nombre) from usuario_usrp where cusr_llave = cerl_usuario) like upper('%' || #{filtroParametro} || '%') or (select upper(cusr_identificacion) from usuario_usrp where cusr_llave = cerl_usuario) = upper( #{filtroParametro}))
